#include <print>
#include <vector>

int main() {
    std::vector<int> scores = {85, 92, 78};

    for (auto& s : scores) {
        s *= 2;
    }
    for (auto s : scores) {
        std::print("{} ", s);
    }
    std::println("");

    for (auto s : scores) {
        s *= 2;   // 少了 &，原件一点没加动，只有手上那份副本被改了
    }

    return 0;
}

